<template><AppFrame><section class="heading mb-6"><div><p class="eyebrow">TRAZABILIDAD</p><h1 class="text-h4 font-weight-bold">Mantenimientos realizados</h1><p class="text-medium-emphasis">Consulta reportes, fotografías, audios y cumplimiento del checklist.</p></div></section><v-card class="panel mb-5" elevation="0" rounded="xl"><v-card-text><v-row><v-col cols="12" md="5"><v-text-field v-model="filters.fecha" type="date" label="Fecha" hide-details/></v-col><v-col cols="12" md="3"><v-btn color="primary" block @click="load">Filtrar</v-btn></v-col></v-row></v-card-text></v-card><v-card class="panel" elevation="0" rounded="xl"><v-data-table :headers="headers" :items="records" :loading="loading"><template #item.fecha_hora="{item}">{{new Date(item.fecha_hora).toLocaleString()}}</template><template #item.estado="{item}"><v-chip color="success" size="small">{{item.estado}}</v-chip></template><template #item.actions="{item}"><v-btn color="primary" variant="text" @click="openDetail(item.id)">Ver reporte</v-btn></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="760"><v-card rounded="xl" title="Detalle del mantenimiento"><v-card-text v-if="detail"><v-row><v-col cols="12" md="6"><b>Máquina:</b> {{detail.maquina?.nombre}}<br><b>Técnico:</b> {{detail.tecnico?.nombre}}<br><b>Observaciones:</b><p>{{detail.observaciones||'Sin observaciones'}}</p></v-col><v-col cols="12" md="6"><v-img v-if="detail.foto_url" :src="detail.foto_url" height="220" cover rounded="lg"/><audio v-if="detail.audio_url" :src="detail.audio_url" controls class="mt-3 w-100"/></v-col></v-row><v-divider class="my-4"/><v-list><v-list-item v-for="item in detail.detalles" :key="item.id" :title="item.cumple?'Cumple':'No cumple'"><template #prepend><v-icon :color="item.cumple?'success':'error'" :icon="item.cumple?'mdi-check-circle':'mdi-close-circle'"/></template><v-list-item-subtitle>{{item.observacion_item}}</v-list-item-subtitle></v-list-item></v-list></v-card-text></v-card></v-dialog></AppFrame></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import AppFrame from '@/components/AppFrame.vue';import api from '@/services/api';const filters=reactive({fecha:new Date().toISOString().slice(0,10)}),records=ref<any[]>([]),loading=ref(false),dialog=ref(false),detail=ref<any>(null);const headers=[{title:'Máquina',key:'maquina.nombre'},{title:'Técnico',key:'tecnico.nombre'},{title:'Fecha',key:'fecha_hora'},{title:'Estado',key:'estado'},{title:'',key:'actions'}];async function load(){loading.value=true;try{records.value=(await api.get('/admin/mantenimientos',{params:filters})).data}finally{loading.value=false}}async function openDetail(id:string){detail.value=(await api.get(`/admin/mantenimientos/${id}`)).data;dialog.value=true}onMounted(load)</script><style scoped>.heading{display:flex}.eyebrow{color:#1976d2;font-weight:800;letter-spacing:.14em}.panel{border:1px solid #e5e7eb}</style>
